		}
		seen[id] = struct{}{}
	}
	return appID, ids, seen, nil
}

// archiveObstructions 是可销毁判断的唯一实现，Check 与 Destroy 共用：
// 同一档案在相同保存状态、相同处理日期下，两处得出一致的结论。
